          setPrototypeOf(values, null)
          values[length] = value
      }
      length++
    }
    switch (length) {
      case 0:
        return small(handle)
      case 1:
        return small(handle, first)
      case 2:
        return small(handle, first, second)
      case 3:
        return small(handle, first, second, third)
      case 4:
        return small(handle, first, second, third, fourth)
      default:
        // Bound VM argument storage while avoiding JSI array reads.
        if (length <= 1024) {
          return apply(many, handle, values!)
        }
        return large(handle, values!)
