  equal(
    new Native('en', {type: 'disjunction', style: 'long'}).format(['A', 'B']),
    'A or B',
    'captured explicit constructor intrinsics'
  )
  equal(
    formatter.format(['A', 'B', 'C', 'D', 'E']),
    'A, B, C, D, and E',
    'captured argument-list application'
  )
  equal(
    formatter.formatToParts(['A', 'B', 'C', 'D', 'E']),
